//! 📄️ Layout exports publish one original-source glyph per plan turn and retain paragraph owners through cancellation.
use super::*;
#[test]
fn layout_text_planning_publishes_bounded_outline_records(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/🎨️export-fidelity/🔣️.json")).unwrap();
 for kind in [LayoutExportKind::Svg,LayoutExportKind::Pdf]{let snapshot:LayoutSnapshot=semio_framework_pack_json::from_json_str(&fixture["artifact"]["document"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let request=LayoutExportRequest{kind,page_id:Some("page-1".into()),snapshot:Arc::new(snapshot),preflight_json:None,parent_document_id:"paragraph".into(),canonical_base_revision_hex:"29".repeat(32)};let source=request.snapshot.stories[0].content.as_ptr();let operation=Operation::new(semio_framework_job::OperationId(93),semio_framework_job::RevisionId(29),semio_framework_job::Generation(3),17);let mut job=LayoutExportJob::from_admitted(operation,(operation.operation,operation.generation),request,ArtifactOutputChunks::new(MAX_LAYOUT_EXPORT_OUTPUT_BYTES));while job.stage==ExportStage::Validate{job.validate_one().unwrap();}let mut turns=0;while job.stage==ExportStage::Plan{let before=job.pdf_items.len();job.plan_one().unwrap();assert!(job.pdf_items.len()-before<=1);assert_eq!(job.request.as_ref().unwrap().snapshot.stories[0].content.as_ptr(),source);turns+=1;assert!(turns<100000);}let outlines=job.pdf_items.iter().filter_map(|item|if let PdfItem::Outline{source,glyph,..}=item{Some((*source,*glyph))}else{None}).collect::<Vec<_>>();assert_eq!(outlines.len(),2);assert!(turns>outlines.len());let oracle=ttf_parser::Face::parse(semio_s_artifact_layout_layout_engine::scene::text_fonts::LAYOUT_SANS,0).unwrap();for((source,glyph),scalar)in outlines.into_iter().zip("Aé".chars()){let record=job.text.as_ref().unwrap().glyph(source,glyph).unwrap();assert_eq!(record.glyph,oracle.glyph_index(scalar).unwrap().0);assert!(record.segment_count>3);}let snapshot=Arc::clone(&job.request.as_ref().unwrap().snapshot);let(outcome,_)=drive_job_batch(job,operation,operation.generation,true,"layout.export.paragraph.cancel",||());assert_eq!(outcome,LayoutExportObserved::Cancelled);drop(snapshot);}
}
